void bch2_print_string_as_lines(const char *prefix, const char *lines,
				bool nonblocking)
{
	const char *p;

	if (!lines) {
		printk("%s (null)\n", prefix);
		return;
	}

	while (*lines) {
		p = strchrnul(lines, '\n');
		if (!*p && string_is_spaces(lines))
			break;

		printk("%s%.*s\n", prefix, (int) (p - lines), lines);
		if (!*p)
			break;
		lines = p + 1;
	}
}

